import { computed, shallowRef } from 'vue'
import { err, ok } from '#core/kernel/result'
import type { ApiError, DomainError, Result } from '#core/kernel/result'

/**
 * Where a query is, as the `status` of Nuxt's useAsyncData: `pending` until it has an answer, then `success` or `error`. Fetching again
 * over an answer stays `success` (the page keeps showing it until the new one replaces it).
 */
export type DataStatus = 'pending' | 'success' | 'error'

const SOMETHING_WENT_WRONG = 'Something went wrong. Please try again.'

/** A failure outside the domain's errors (the server could not be reached, or a bug): its detail goes to the console, the UI gets a generic message. */
export const unexpected = (cause: unknown): ApiError<never> => {
  console.error(cause)
  return { type: 'unexpected', message: SOMETHING_WENT_WRONG }
}

const isDomainError = (value: unknown): value is DomainError =>
  typeof value === 'object' && value !== null && typeof (value as DomainError).type === 'string' && typeof (value as DomainError).message === 'string'

/**
 * What a server route answered (a `$fetch` of it): its value, or the domain error it answered with. The route sends the error as the
 * `data` of its HTTP error (`unwrapOrThrow`); anything else is `unexpected`.
 */
export const fromRoute = async <T, E extends DomainError>(call: Promise<T>): Promise<Result<T, ApiError<E>>> => {
  try {
    return ok(await call)
  } catch (cause) {
    const sent = typeof cause === 'object' && cause !== null ? (cause as { data?: { data?: unknown } }).data?.data : undefined
    // The route answers only the errors of its domain: the type says which they are.
    return err(isDomainError(sent) ? sent as E : unexpected(cause))
  }
}

/** An error a call answered, carried through what knows only thrown errors (a TanStack query or transaction) to whoever reads it. */
export class Answered extends Error {
  readonly error: ApiError
  constructor(error: ApiError) {
    super(error.message)
    this.error = error
  }
}

/** What a call that threw failed with: the error it carried (`Answered`), or something unexpected. */
export const failureOf = <E extends DomainError>(cause: unknown): ApiError<E> =>
  cause instanceof Answered ? cause.error as ApiError<E> : unexpected(cause)

/**
 * An action: `run` calls `call` and answers its Result, never throws (a call that does is `unexpected`). `pending` is true while any of
 * its runs is, `error` is the last run's error.
 */
export const useAction = <Args extends unknown[], Output, E extends DomainError>(call: (...args: Args) => Promise<Result<Output, ApiError<E>>>) => {
  const pending = shallowRef(false)
  const error = shallowRef<ApiError<E>>()
  let running = 0
  const run = async (...args: Args): Promise<Result<Output, ApiError<E>>> => {
    running += 1
    pending.value = true
    error.value = undefined
    try {
      const result = await call(...args)
      if (!result.ok) error.value = result.error
      return result
    } catch (cause) {
      const failure = failureOf<E>(cause)
      error.value = failure
      return err(failure)
    } finally {
      running -= 1
      pending.value = running > 0
    }
  }
  return { run, pending, error }
}

/** What `fromLiveQuery` reads of a TanStack DB live query (`useLiveQuery`). */
export interface LiveQuery<T> {
  readonly data: { readonly value: T }
  readonly isReady: { readonly value: boolean }
  readonly isLoadingError: { readonly value: boolean }
  readonly isCrashed: { readonly value: boolean }
  readonly isSyncError: { readonly value: boolean }
}

/**
 * A live query with the contract of Nuxt's useAsyncData: `data`, `status` and `error` are refs, `refresh()` refetches what it reads.
 * It is `error` when its first load failed, its store broke or a later sync failed (its data stays), else `success` once ready.
 */
export const fromLiveQuery = <T>(query: LiveQuery<T>, refetch: () => Promise<unknown>) => {
  const failed = () => query.isLoadingError.value || query.isCrashed.value || query.isSyncError.value
  const status = computed<DataStatus>(() => failed() ? 'error' : query.isReady.value ? 'success' : 'pending')
  // The collection reports its own failure; the UI gets the generic message.
  const error = computed<ApiError<never> | undefined>(() => status.value === 'error' ? { type: 'unexpected', message: SOMETHING_WENT_WRONG } : undefined)
  const refresh = async () => {
    await refetch()
  }
  return { data: query.data, status, error, refresh }
}
